// Companion block members clashing with JVM members generated by the compiler.

// $default stubs: foo(I) and static foo(LC;I) differ, but both foo$default stubs are (LC;IILjava/lang/Object;).
class DefaultStubs {
    <!CONFLICTING_JVM_DECLARATIONS!>fun foo(a: Int = 1)<!> = a

    companion {
        <!CONFLICTING_JVM_DECLARATIONS!>fun foo(c: DefaultStubs, a: Int = 2)<!> = a
    }
}

// Overloads generated by @JvmOverloads.
class Overloads {
    <!CONFLICTING_JVM_DECLARATIONS!>fun f()<!> = "instance"

    companion {
        @JvmOverloads
        <!CONFLICTING_JVM_DECLARATIONS!>fun f(a: Int = 1) = "static"<!>
    }
}

