    companion {
        <!CONFLICTING_JVM_DECLARATIONS!>val x<!> = 2
    }
}

// Getters differ by return type, but both properties generate the synthetic 'getX$annotations()V'.
@Target(AnnotationTarget.PROPERTY)
annotation class Ann

class <!CONFLICTING_JVM_DECLARATIONS!>AnnotationsMethods<!> {
    @Ann val x: Int get() = 1

    companion {
        @Ann val x: String get() = "s"
    }
}

// Non-private fields of companion block and companion object properties are not renamed.
class Fields {
    companion {
        <!CONFLICTING_JVM_DECLARATIONS!>@JvmField val x<!> = 1
    }

    companion object {
        <!CONFLICTING_JVM_DECLARATIONS!>@JvmField val x<!> = 2
